    translation: '唉呀呀，多么高峻啊！蜀道的艰难，比上青天还难！蚕丛和鱼凫，开国的历史多么遥远迷茫！从那以来四万八千年，一直不和秦地相通人烟。西边挡着太白山，只有鸟可以飞过，可以横穿到达峨眉山顶。地崩山塌壮士牺牲了生命，然后才有了天梯石栈把山岩钩连起来。上面有迫使日神六龙车转回的高峰，下面有波涛翻滚曲折回旋的河流。黄鹤的飞翔尚且不能越过，猿猴想要攀越也发愁无法攀援。青泥岭的路多么曲折盘旋，百步之内九次转弯绕着山崖。摸着参星和井星，屏住呼吸，用手捂着胸口坐下来长叹。请问你西游什么时候回来？可怕的道路上险峻的山岩无法攀登。只看到悲鸣的鸟在古树上号叫，雄鸟在前飞，雌鸟跟从在林间环绕。又听到杜鹃在月夜啼叫，使空山充满了愁思。蜀道的艰难，比上青天还难，使人听了这些脸色都变了！连绵的山峰离天不到一尺，枯松倒挂着靠在绝壁上。飞流的瀑布争相发出喧闹声，冲撞着崖石翻转着，万道山谷发出雷鸣般的回声。蜀道的险就是这样，唉，远方的人为什么要来啊！剑阁高峻崎岖而突兀，一个人守住关口，万人也打不开。守关的人如果不是亲信，就会变成豺狼一样的人。早晨要躲避猛虎，傍晚要躲避长蛇，它们磨牙吸血，杀人如麻。锦城虽然说安乐，不如早早回家。蜀道的艰难，比上青天还难，侧身向西望着，长长地叹息！',
    literaryInfo: {
      authorBio: '李白（701年—762年），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人誉为“诗仙“。',
      background: '此诗大约作于天宝初年，李白初入长安之时。据说贺知章读到此诗，惊叹不已，称李白为“谪仙人“。',
      significance: '此诗以奇绝的想象和夸张的手法，描绘了蜀道的险峻壮美。"蜀道之难，难于上青天"三次反复咏叹，既是全诗的主旋律，又起到层层推进的作用。诗中"上有六龙回日之高标，下有冲波逆折之回川"以上下对比极写山川之险，"黄鹤之飞尚不得过，猿猱欲度愁攀援"以物衬人更显蜀道之难，末段以剑阁险要暗含对藩镇割据的隐忧，是李白浪漫主义诗歌的巅峰之作。',
    },
