    translation: '古代求学的人一定有老师。老师，是用来传授道理、教授学业、解答疑难问题的人。人不是生下来就懂得道理的，谁能没有疑惑？有了疑惑，如果不跟从老师学习，那些成为疑惑的问题，就始终不能解决了。出生在我前面的人，他懂得道理本来比我早，我跟从他把他当作老师；出生在我后面的人，他懂得道理也比我早，我也跟从他学习把他当作老师。我学习的是道理，哪管他是生在我之前还是生在我之后呢？所以无论地位高低贵贱，无论年纪大小，道理存在的地方，就是老师存在的地方。唉！从师求学的风尚不流传已经很久了！想要人没有疑惑很难了！古代的圣人，他们超出一般人很远了，尚且跟从老师向老师请教；现在的一般人，他们才智低于圣人很远，却以向老师学习为耻。因此圣人更加圣明，愚人更加愚昧。圣人之所以成为圣人，愚人之所以成为愚人，大概都是因为这样吧？人们爱他们的孩子，就选择老师来教育他；对于他自己呢，却以从师学习为耻，真是糊涂啊。那些孩子们的老师，是教他们读书、学习断句的，不是我所说的传授道理、解答疑难问题的老师。不知句读就不能解决疑惑，有的向老师学习，有的却不向老师学习，小的方面学习，大的方面却遗漏了，我看不出他有什么明智的。巫医、乐师和各种工匠这些人，不以互相学习为耻。士大夫这类人，听到称“老师“称“弟子“的，就成群聚在一起讥笑人家。问他们，就说：“他和他年龄差不多，学问也差不多，以地位低的人为师，就感到十分羞耻，以官位高的人为师，就觉得是近于谄媚。“唉！从师学习的风尚不能恢复，由此可知了。巫医、乐师和各种工匠这些人，君子不屑与他们并列，现在他们的智慧竟然反而赶不上这些人，真是奇怪啊！圣人没有固定的老师。孔子曾以郯子、苌弘、师襄、老聃为师。郯子这些人，他们的贤能比不上孔子。孔子说：“三个人同行，其中一定有可以做我老师的人。“所以学生不一定不如老师，老师不一定比学生有才智，听到的道理有早有晚，学问技艺各有专长，如此罢了。李家的儿子名叫蟠，十七岁，喜欢古文，六经的经文和传文都普遍学习了，不受时俗的拘束，向我学习。我赞许他能行古人从师之道，写了这篇《师说》来赠送给他。',
    literaryInfo: {
      authorBio: '韩愈（768年—824年），字退之，河南河阳人，唐代文学家、思想家，唐宋八大家之首。',
      background: '此文作于贞元十八年（802年），韩愈任国子监四门博士时。当时士大夫阶层耻于从师，韩愈不顾流俗，收召后学，作此文以倡导从师之道。',
      significance: '此文针对当时"士大夫之族，曰师曰弟子云者，则群聚而笑之"的社会风气而作，以"师者，所以传道受业解惑也"定义教师职能，以"道之所存，师之所存"确立择师标准，以"弟子不必不如师，师不必贤于弟子"打破师道尊严。全文以对比论证为主，将古之圣人与今之众人、爱其子与于其身、巫医百工与士大夫之族层层对照，说理严密而有锋芒，是唐代古文运动的代表作。',
    },
