    translation: '壬戌年秋天，七月十六日，我与客人在赤壁下面泛舟游览。清风缓缓吹来，水面上不起波澜。举起酒杯劝客人饮酒，吟诵《诗经·陈风·月出》中关于明月的诗句，歌唱其中的窈窕篇章。一会儿，月亮从东山上升起，在斗宿和牛宿之间徘徊。白茫茫的雾气弥漫江面，水光与天色相接。任凭小船在宽广的江面上飘荡，越过万顷的江面。多么辽阔呀，像是凌空乘风飞行，不知道将停留在何处；多么飘逸呀，好像超越了尘世，羽化成仙飞向天庭。于是喝酒喝得非常高兴，敲击着船帮唱起歌来。歌词说：“桂木做的棹，兰木做的桨，划破月光下的清波，逆着流水迎着光。我的情怀悠远啊，眺望美人在天的那一方。“客人中有一位吹洞箫的，按着歌声吹箫伴奏。箫声呜呜地响，像怨恨，像思慕，像哭泣，像倾诉，尾音凄切婉转，像细丝一样不断。能使深谷中潜伏的蛟龙起舞，能使孤舟上的寡妇落泪。我变了脸色，整理衣襟端正地坐着问客人说：“箫声为什么这样哀怨呢？“客人说：“\'月明星稀，乌鹊南飞\'，这不是曹操的诗句吗？向西望是夏口，向东望是武昌，山川环绕，草木茂盛苍翠，这不是曹操被周瑜打败的地方吗？当他攻破荆州，攻下江陵，顺流东下的时候，战船千里相接，旌旗遮蔽了天空，面对长江喝酒，横执长矛吟诗，本来是一代的英雄啊，可如今在哪里呢？何况我与你在江边的水渚上打渔砍柴，与鱼虾作伴，与麋鹿交友，驾着一叶小舟，举起葫芦做的酒杯互相劝饮。像蜉蝣一样寄生在天地之间，渺小得像大海中的一粒粟米。哀叹我们生命的短暂，羡慕长江的无穷无尽。希望拉着神仙遨游各地，与明月相拥而永远终了。知道这不可能轻易得到，只好把悲凉的箫声托付给秋风。“我说：“你也了解那江水和明月吗？江水总是不停地流逝，但它们并没有流走；月亮有圆有缺，但它终究没有消减也没有增加。如果从那变动的一面来看，那么天地间的万事万物连一眨眼的工夫都不曾保持过原状；从那不变的一面来看，那么万物和我们一样都是永存的，又有什么可羡慕的呢？何况天地之间，凡物各有自己的归属，如果不属于我自己，即使是一丝一毫也不能强求。只有江上的清风和山间的明月，耳朵听到了才成为声音，眼睛看到了才成为景色，获取它没有人禁止，享用它不会穷尽，这是大自然的无穷无尽的宝藏，是我和你可以共同享受的。“客人高兴地笑了，洗净酒杯重新斟酒。菜肴和果品都被吃光了，酒杯和菜盘杂乱地放着。大家互相枕着靠着睡在船中，不知不觉东方已经亮了。',
    literaryInfo: {
      authorBio: '苏轼（1037年—1101年），字子瞻，号东坡居士，北宋文学家、书画家，唐宋八大家之一。',
      background: '宋神宗元丰五年（1082年），苏轼谪居黄州时两次游赤壁，写下前后《赤壁赋》，此为前赋。',
      significance: '此赋通过主客问答的形式，展现了由乐转悲、由悲而悟的情感历程。客以曹操"月明星稀"之句引发人生短暂的悲叹，苏轼以"逝者如斯，而未尝往也"的辩证思考化解悲愁，提出"造物者之无尽藏"的达观态度。全篇写景如画，"白露横江，水光接天"意境旷远，说理深邃，"自其不变者而观之，则物与我皆无尽也"融庄禅思想于一炉，体现了苏轼在贬谪中的精神超越，被誉为宋代文赋的巅峰之作。',
    },
