    translation: '到处寻找，到处寻觅，冷冷清清，凄凄惨惨悲悲戚戚。忽暖忽寒的时候，最难调养休息。喝了几杯薄酒，也抵挡不住晚风的寒意。正在伤心的时候一群大雁飞过，恰好是旧时相识。满地都是凋零的菊花，枯萎破败，如今有谁还会来采摘？守着窗子，一个人怎么熬到天黑！梧桐树上又加上细雨，到了黄昏时分还点点滴滴。这种情形，怎么是一个“愁“字概括得了的！',
