    translation: '深秋季节，我独自站立在橘子洲头，望着滔滔的湘水向北奔流。看万千山峰全都变成了红色，一层层树林好像染过颜色一样；江水清澈澄碧，一艘艘大船乘风破浪，争先恐后。鹰在广阔的天空里飞，鱼在清澈的水里游，万物都在秋光中争着过自由自在的生活。面对广阔的宇宙惆怅感慨，问这苍茫大地的盛衰兴废，由谁来决定主宰呢？曾经和许多同志携着手来游，回忆起过去那些不平凡的岁月令人难忘。同学们正值青春年少，风采才能正盛；书生们的意气奔放，强劲有力。评论国家大事，写出激昂慷慨的文章，把那些达官贵人视如粪土。可曾记得，当年我们在江中游泳，激起的波浪几乎阻止了飞快行驶的船只？',
