    translation: '一边喝酒一边高歌，人生短促日月如梭！好比晨露转瞬即逝，失去的时日实在太多。席上歌声激昂慷慨，忧郁长久填满心窝。靠什么来排解忧闷？唯有狂饮方可解脱。那穿着青领的学子哟，你们令我朝夕思慕。正是因为你们的缘故，我一直低唱吟诵至今。阳光下鹿群呦呦欢鸣，悠然自得啃食野草。我有尊贵的宾客，弹瑟吹笙热情宴请。如同那皎洁的月亮，什么时候才能摘取呢？忧伤从中涌起，不能断绝。穿过纵横交错的小路，劳驾你们来问候我。久别重逢欢宴畅谈，心中思念着旧日的恩情。月光明亮星光稀疏，一群寻巢乌鹊向南飞去。绕树飞了三周却没敛翅，哪里才有它们栖身之所？高山不辞土石才见巍峨，大海不弃涓流才见壮阔。像周公那样礼贤下士，天下人心自然归附。',
