    translation: '航海的人谈论瀛洲，烟波浩渺实在难以寻求；越地的人说起天姥山，云霞忽明忽暗有时可以看见。天姥山直插天际横卧天边，山势超出五岳遮掩了赤城。天台山高达四万八千丈，对着天姥山好像要拜倒在东南方。我想依据这些传说梦游吴越，一夜之间飞渡过月下的镜湖。湖上的月光照着我的身影，送我到了剡溪。谢灵运住宿的地方如今还在，清澈的溪水荡漾，猿猴的啼声清厉。脚上穿着谢公屐，攀登直上青云的阶梯。半山腰就看见了海上的日出，空中传来天鸡的叫声。千岩万壑山路曲折方向不定，迷恋着花倚靠着石头天色已经暗了。熊在咆哮龙在长吟，震响着岩中的泉水，深林战栗层巅惊动。云层黑沉沉啊将要下雨，水波荡漾啊升起烟雾。闪电劈开天空，山丘峰峦崩塌。仙洞的石门，轰隆一声从中间打开。洞中青天广阔看不到底，日月照耀着金银台阁。彩虹做衣裳啊清风做骏马，云中的神仙纷纷降下来。老虎弹瑟啊鸾鸟拉车，仙人们排列得像麻一样密集。忽然觉得心惊魄动，恍然惊醒发出长长的叹息。醒来时只看到枕席，刚才梦中的烟霞胜景已经消失了。世间行乐也不过如此，自古以来万事都像东流水一去不返。离开你们什么时候才能回来？暂且把白鹿放养在青崖之间，想要行走时就骑上它去访问名山。怎么能低眉弯腰去侍奉权贵，让我不能开怀欢笑！',
