      background: '此词约作于王安石退居金陵后，登高怀古，对六朝兴亡发出深沉感慨。',
      significance: '此词是宋代怀古词的代表作，上阕以"千里澄江似练，翠峰如簇"的壮美景色写金陵形胜，"彩舟云淡，星河鹭起"则于壮阔中见灵动。下阕以"门外楼头，悲恨相续"六朝覆亡的教训警醒当世，"至今商女，时时犹唱，后庭遗曲"以曲终奏雅的方式收束，暗示北宋正重蹈覆辙。全词意境壮阔，感慨深沉，将写景、咏史、讽谏融为一体，王安石自云"至今商女"三句是他最得意的词句。',
