    translation: '洞庭湖与青草湖相连，将近中秋，没有一丝风的痕迹。玉镜般的湖面三万顷，载着我这一叶小舟。皎洁的月亮分洒清辉，银河与月影交映，水天上下都是一片澄澈。悠然间心领神会，这种妙处很难与你述说。回想在岭南任职的这一年，只有孤月作伴自照，肝胆肺腑都如冰雪般高洁。短发稀疏衣袖生寒，平稳地泛舟在广阔的湖面上。把西江的水全部舀来，用北斗星当酒杯细细斟酌，以天地万象为宾客。敲击船帮独自长啸，忘却了今夕是何年。',
