    translation: '庖丁给文惠君宰杀牛，手触到的，肩抵住的，脚踩着的，膝抵住的，哗哗作响，进刀时发出騞騞的声音，没有不合乎音律的：既合乎《桑林》舞曲的节拍，又合乎《经首》乐章的节奏。文惠君说："啊，好极了！技术怎么能达到如此高超的境界呢？"庖丁放下刀回答说："我所爱好的是道，已经超越技术了。我刚开始宰牛的时候，看到的没有不是整头牛的。三年之后，就未曾看到过整头牛了。到了现在，我只用心神去和牛接触而不需要用眼睛去看，感官停止了而心神在活动。顺着牛的天然生理结构，劈开大的缝隙，顺着大的空处，按照它本来的结构，筋脉经络相连和筋骨结合的地方都没有用刀去碰过，更何况大骨头呢！好的厨师一年换一把刀，他们是用刀割；一般的厨师一个月换一把刀，他们是用刀砍。现在我的刀用了十九年了，宰杀的牛有几千头了，而刀刃就像刚从磨刀石上磨出来一样。牛的骨节有间隙，而刀刃很薄；用薄薄的刀刃插入有空隙的骨节，宽宽绰绰地运刀肯定大有余地了，因此十九年了刀刃还像刚从磨刀石上磨出来一样。虽然如此，每当碰到筋骨交错聚结的地方，我看到那里难以下刀，就小心翼翼地提高警惕，目光专注，动作缓慢。刀子微微一动，牛就哗啦解体了，如同泥土散落在地上。我提着刀站立，四下环顾，为此悠然自得，心满意足，把刀擦干净收藏起来。"文惠君说："好极了！我听了庖丁的话，懂得了养生的道理了。"',
