    translation: '意映爱妻如面：我现在用这封信与你永远分别了！我写这封信的时候，还是世上一个人；你看这封信的时候，我已经成为阴间一鬼了。我写这封信，泪珠和笔墨一起落下，不能写完信就想放下笔，又怕你不体察我的衷情，说我忍心抛弃你而死，说我不知道你不想让我死，所以就忍着悲痛为你诉说。我最爱你，就是这一爱你的念头，使我勇于走向死亡。我自从遇到你以来，常常希望天下的有情人都成眷属；然而遍地血腥，满街狼犬，称心快意的人有几个？司马青衫，我不能学太上忘情。古语说：仁者"老吾老以及人之老，幼吾幼以及人之幼"。我充吾爱汝之心，助天下人爱其所爱，所以敢先汝而死，不顾你啊。你要体察我的这番心意，在哭泣之余，也以天下人为念，当也乐于牺牲我一身之福利，为天下人谋永福。哎！巾短情长，所未尽者，还有万千，你可以由此想象了。我现在再没有别的话了！我在九泉之下远远地听到你的哭声，当也会哭声相应。我以前不曾相信有鬼，现在又希望它真有。现在的人又说有电报通讯，那我的灵魂也一定能感应到。我在九泉之下，一定依偎着你，不会离开你。你记得吗？四五年前的一个晚上，我曾经对你说："与其让我先死，不如让你先死。"你刚听了这话不高兴，后来我经过几次向你解释，你虽然认为我的话对，但也没办法。我说这话时，的确是愿意你先死，让我来承担悲痛啊。哎！谁知道我终究比你先死呢？我确实不能忘记你啊！回想后街的房屋，入门穿过走廊，过前后厅，又三四折，有一个小厅，厅旁有一间房，是我和你共同居住的地方。初婚三四个月，冬天望日前后，窗外稀疏的梅枝筛下月影，掩映遮覆；我和你并肩携手，低低私语，什么话不说？什么情不诉？到现在想起来，只剩下泪痕。又回忆六七年前，我逃亡回家又出门的时候，你不哭还希望我回来，所以才把心事隐瞒着，只说希望我回来。我十几天前回到家，就想乘便把这次出行的事告诉你，等到和你相对，又不能开口，况且因你已怀孕了，更怕不能胜过悲痛，所以只好天天求酒买醉。哎！当时我内心的悲痛，是不能用笔墨来形容的。我确实愿意和你相守到死，但从今天的形势看，天灾可以死，盗贼可以死，瓜分之日可以死，奸官污吏虐民可以死，我们处在今天的中国，国内无时无地不可以死，到那时使吾眼睁睁看你死，或使你眼睁睁看我死，我能做到吗？你愿意吗？即使能不死，而离散不相见，徒使两地眼光成穿骨的思念，古来失恋的人几时断绝，我怎能和你一样呢？我之不得不先你而死。哎！我此生幸运，又不幸生在今天的中国。我有幸有你，又不幸生在今天的中国。我不忍独善其身。嗟夫！你这身子正妊娠，我怀疑是个女儿，女儿一定像你，我心里很安慰。或者又是个男孩，则也要教他以父亲的志向为志向，那我死后还有两个林觉民在呢。很好，很好！我们家的后日当更兴旺。我家以后当会很贫穷，贫穷没有什么苦恼，清净过日子罢了。你现在已有身孕，更要节哀，也要爱惜身体，爱护孩子。我从来没有把我的志向告诉你，是我的不对；但是告诉你，又怕你天天为我担忧。我为国牺牲，死也甘愿。孩子，你要好好教导他，使他像我。你肚里的孩子，我猜是女的，如果是女的就一定像你，我非常欣慰。孩子，要像父亲一样，有一副侠义的心肠。还有，我死后，家里自然穷，但我希望你能做点手工，维持生活，这样比倚赖人家强得多。嗟夫！我平生未曾以我的志向告诉你，这是我的不对；然而告诉你，又恐你日日为我担忧。我为国牺牲，百死不辞。吾爱汝至，汝唯忘我，天下之人不当死而死与不愿离而离者，不可数计，钟情如我辈者，能忍之乎？此吾所以敢率性就死不顾汝也。吾今死无余憾，国事成不成自有同志者在。依新已五岁，转眼成人，汝其善抚之，使之肖我。汝腹中之物，疑其女也，女必像汝，我心甚慰；或又是男，则亦教其以父志为志，则我死后尚有二意洞在也，甚幸甚幸！吾家后日当甚贫，贫无所苦，清静过日而已。吾今与汝无言矣！吾居九泉之下，遥闻汝哭声，当哭相和也。吾平日不信有鬼，今则又望其真有；今人又言心电感应有道，吾亦望其言是实，则吾之死，吾灵尚依依旁汝也，汝不必以无侣悲！吾生平未尝以吾志语汝，是吾不是处；然语之，又恐汝日日为吾担忧。吾牺牲百死而不辞，而使汝担忧，的的非吾所忍。吾爱汝至，所以为汝谋者惟恐未尽。汝幸而偶我，又何不幸而生今日之中国！吾幸而得汝，又何不幸而生今日之中国！卒不忍独善其身。嗟夫！巾短情长，所未尽者，尚有万千，汝可以模拟得之。吾今不能见汝矣！汝不能舍吾，其时时于梦中得我乎！恸甚！辛未三月念六夜四鼓，意洞手书。家中诸母皆通文，有不解处，望请其指教，当尽吾意为幸。,',
