    translation: '安石启：昨天承蒙您来信指教，我私下以为与您交往相好的时间很长了，但讨论政事常常意见不合，这是因为所持的政治主张多有不同的缘故。虽然想强作解释，最终一定不会被您理解，所以只简略地回了一封信，不再一一为自己辩解。又想到承蒙您看重我，在书信往来上不应草率，所以现在详细说明原委，希望您或许能原谅我。大凡读书人所争论的，特别在于名义和实际是否相符，名义和实际的关系明确了，天下的道理也就清楚了。现在您用来指教我的，认为我侵夺官员职权、制造事端、征取财利、拒绝劝谏，因此招致天下人的怨恨和诽谤。我却认为：从君主那里接受命令，在朝廷上议定法度并加以修订，然后交给主管官员去执行，不算是侵夺职权；推行先王的政令，来兴利除弊，不算是制造事端；为天下治理财政，不算是征取财利；批驳谬论，斥责巧言谄媚的人，不算是拒绝劝谏。至于怨恨和诽谤之多，本来早就知道会这样的。人们习惯于得过且过已经不是一天了，士大夫大多把不关心国事、附和世俗来讨好众人当作美德，皇上想要改变这种状况，而我不衡量反对者的多少，想要出力帮助皇上来对抗他们，那么众人怎么会不大吵大闹呢？盘庚迁都的时候，怨恨的是百姓，不仅是朝廷士大夫而已；盘庚不因为有怨恨的人就改变他的计划，是因为考虑到合理然后行动，认为正确就看不出有什么可以后悔的。如果您责备我在位时间长，没能帮助皇上大有作为，来造福百姓，那我承认有罪；如果说现在应当什么事都不做，只是墨守前人的陈规而已，那就不是我所敢认同的。',
