    translation: '六国灭亡，不是因为武器不锋利，仗打得不好，弊端在于贿赂秦国。贿赂秦国就削弱了自己的力量，这就是灭亡的原因。有人说：六国互相灭亡，全都是因为贿赂秦国吗？回答说：不贿赂秦国的国家因为贿赂秦国的国家而灭亡。原因是：强国不能独自保存。所以弊端在于贿赂秦国啊。秦国用战争以外的方式获取土地，小的得到邑，大的得到城，比起自己通过战争夺取的土地，实际多到百倍；诸侯贿赂秦国所失去的土地，比起战败所失去的土地，实际也多到百倍。那么秦国最大的欲望，诸侯最大的祸患，本来就不在于战争。想想他们先辈的祖辈，冒着霜露，披荆斩棘，才有了这少许的土地。子孙对它却不珍惜，拿它送给别人，像丢弃小草一样。今天割让五座城，明天割让十座城，然后才能求得一夜安眠。起来看看四周边境，而秦国的军队又到了。既然如此，那么诸侯的土地有限，强秦的贪欲没有满足，奉送得越多，侵凌得越急。所以不用战争，而强弱胜负已经判定了。至于颠覆的结局，理所当然。古人说："用土地侍奉秦国，就像抱着柴草去救火，柴草没有烧完，火就不会熄灭。"这话对了。齐国不曾贿赂秦国，终究也跟着五国灭亡了，为什么呢？是因为和秦国交好而不帮助五国啊。五国已经灭亡，齐国也不能幸免了。燕国和赵国的国君，起初有远大的谋略，能够守住他们的国土，坚持大义而不贿赂秦国。所以燕国虽然是个小国却后灭亡，这就是用兵的功效。到了燕太子丹用荆轲刺秦王作为计策，才招致了祸患。赵国曾经五次和秦国交战，两次败而三次胜。后来秦国两次攻打赵国，李牧接连打退了它。等到李牧因为谗言被杀，邯郸才成为秦国的一个郡。可惜它用兵却不能坚持到底啊。况且燕赵处在秦国把其他国家几乎消灭干净的时候，可以说智谋和力量都很单薄，战败而灭亡，实在是不得已的事。假使韩、魏、楚三国都爱惜他们的土地，齐国不依附秦国，燕国的刺客不行刺，赵国的良将还活着，那么胜败的命运，存亡的道理，如果和秦国相比较，或许不容易估量。唉！如果以贿赂秦国的土地封赏天下的谋臣，以侍奉秦国的心意礼遇天下的奇才，合力向西对付秦国，那么我恐怕秦国人连吃饭都咽不下去。可悲啊！有这样的有利形势，却被秦国积久的威势所胁迫，一天天、一月月地割让土地，以至于走向灭亡。治理国家的人不要让自己被积久的威势所胁迫啊！六国和秦国都是诸侯，他们的势力比秦国弱，却还有可以不贿赂而取胜的优势。如果凭着全天下那么大的地方，却追随六国灭亡的前例，这就比六国还要低下了。,',
