    translation: '春天的江潮水势浩荡，与大海连成一片，一轮明月从海上升起，好像随着潮水一起涌出来。月光照耀着春江，随着波浪闪耀千万里，什么地方的春江没有明亮的月光！江水曲曲折折地绕着花草丛生的原野流淌，月光照射着开满鲜花的树林好像细密的雪珠的闪光。空中的霜飞察觉不到，白沙和月色融合在一起看不清楚。江水和天空成一色没有一点细微的灰尘，明亮的天空中只有一轮孤月高悬。江边上什么人最初看见月亮？江上的月亮哪一年最初照耀着人？人生一代一代地无穷无尽，江上的月亮一年一年地总是相似。不知道江上的月亮等待着什么人，只看到长江送走了一江流水。一片白云悠然飘去，青枫浦上远行的人满怀忧愁。谁家今夜在扁舟中漂泊？何处有人在明月下的楼上思念？月光在楼上徘徊不忍离去，应该照在离人的梳妆台上。月光照在闺中的门帘上卷也卷不去，照在捣衣砧上拂了又来。这时互相望着却听不到声音，希望随着月光流去照耀着你。鸿雁飞得再远也飞不出月光，鱼龙潜跃在水面上激起波纹。昨夜梦见花落在幽静的水潭上，可怜春天过半还不能回家。江水带着春光将要流尽，江潭上的落月又西斜。斜月沉入海雾中，碣石与潇湘相距无限遥远。不知道趁着月光有多少人归来，落月摇荡着离愁别绪洒满了江边的树林。',
