    translation: '大学的宗旨，在于彰明美好的德行，在于使民众更新向善，在于达到最完善的境界。知道应当止步于至善的境界，然后才能有确定的方向；有了确定的方向，然后才能内心宁静；内心宁静，然后才能安稳；安稳然后才能思虑周详；思虑周详然后才能有所收获。万物都有本有末，事情都有始有终，知道先做什么后做什么，就接近于大学之道了。古代想要彰明美好德行于天下的人，先要治理好自己的国家；想要治理好自己的国家，先要管理好自己的家族；想要管理好自己的家族，先要修养好自身的品德；想要修养好自身的品德，先要端正自己的内心；想要端正自己的内心，先要使自己的意念真诚；想要使自己的意念真诚，先要获得知识；获得知识在于推究事物的原理。事物原理被推究后知识才能达到，知识达到后意念才能真诚，意念真诚后内心才能端正，内心端正后自身品德才能修养好，自身品德修养好后家族才能管理好，家族管理好后国家才能治理好，国家治理好后天下才能太平。从天子一直到平民，一概都以修养自身为根本。',
