    translation: '孟子说："人人都有怜恤别人的心。先王有怜恤别人的心，于是就有了怜恤别人的政治；以怜恤别人的心来施行怜恤别人的政治，治理天下就像在手心里运转一样容易。之所以说人人都有怜恤别人的心，是因为现在有人突然看到一个小孩将要跌入井里，都会产生惊骇同情的心情——这不是为了和小孩子的父母结交，不是为了在乡邻朋友中博取名誉，也不是因为厌恶那小孩子的哭声才这样的。由此看来，没有同情心的人不是人；没有羞耻心的人不是人；没有谦让心的人不是人；没有是非心的人不是人。同情心是仁的开端；羞耻心是义的开端；谦让心是礼的开端；是非心是智的开端。人有这四种开端，就像人有四肢一样。有这四种开端却说自己不行的，是自暴自弃的人；说他的君主不行的，是残害君主的人。凡是具备这四种开端的人，如果知道都去扩大充实它们，就像火刚点燃，泉水刚涌出。如果能扩充它们，就足以安定天下；如果不能扩充它们，就连侍奉父母都做不到。"',
