    translation: '三十根辐条汇集到一个车毂上，正是车毂中空的地方，才有了车的功用。揉捏黏土制成器皿，正是器皿中空的地方，才有了器皿的功用。开凿门窗建造房屋，正是门窗中空的地方，才有了房屋的功用。所以"有"给人便利，"无"发挥了它的作用。踮起脚尖的人站不稳，跨大步的人走不远，自我炫耀的人不聪明，自以为是的人不能明辨是非，自我夸耀的人没有功劳，自高自大的人不能长久。从道的角度来衡量，这些叫做剩饭赘瘤，万物都厌恶它们，所以有道的人不这样做。了解别人的是智慧，了解自己的是明智。战胜别人的是有力，战胜自己的是刚强。知足的是富有，坚持力行的是有志。不离失根基的才能长久，身死而不被遗忘的是长寿。事物安稳时容易维持，事物没有征兆时容易谋划，事物脆弱时容易消解，事物微小时容易散失。在事情没有发生时就去做，在祸乱没有产生前就治理。合抱粗的大树，生于微小的幼芽；九层的高台，起于一筐筐泥土；千里的行程，始于脚下第一步。',
