    translation: '惠子对庄子说："魏王送给我大葫芦的种子，我种下后结出的葫芦有五石那么大。用来盛水，它的坚固程度不够自己承受。剖开来做瓢，又太大没有地方放得下。它不是不大，我因为它没有用处就把它砸碎了。"庄子说："您实在是不善于使用大的东西啊。宋国有人善于制造防止手冻裂的药，世世代代以漂洗丝絮为业。客人听说了，请求用百金购买他的药方。他召集全家族商量说：\'我们世世代代漂洗丝絮，不过赚几金；现在一下子卖技术就能得百金，请卖给他吧。\'客人得到药方，拿去游说吴王。越国发难入侵，吴王派他率领军队。冬天，和越国人水战，大败越国人，吴王分封土地给他。同样是不使手冻裂的药方，有人因此得到封地，有人免不了漂洗丝絮，这是因为用途不同。现在你有五石大的葫芦，为什么不把它系在身上作为渡水的浮器而浮游于江湖之上，却忧虑它太大无处可放呢？那么您还是心窍不通啊！"',
