    translation: '圣人是把治理天下作为职业的人，一定要知道混乱从何而起，才能治理；不知道混乱从何而起，就不能治理。这是为什么呢？应当考察混乱从何而起？起于不相爱。臣子不孝敬君父，就是所谓的混乱。儿子只爱自己，不爱父亲，所以损害父亲来使自己得利；弟弟只爱自己，不爱哥哥，所以损害哥哥来使自己得利；臣子只爱自己，不爱君主，所以损害君主来使自己得利：这就是所谓的混乱。即使父亲不慈爱儿子，哥哥不慈爱弟弟，君主不慈爱臣子，这也是天下所谓的混乱。父亲只爱自己，不爱儿子，所以损害儿子来使自己得利；哥哥只爱自己，不爱弟弟，所以损害弟弟来使自己得利；君主只爱自己，不爱臣子，所以损害臣子来使自己得利。这是为什么呢？都是起于不相爱。如果使天下人都互相爱，爱别人就像爱自己，还有不孝的人吗？看待父亲哥哥和君主就像看待自己一样，怎么会做出不孝的事？还有不慈爱的人吗？看待儿子弟弟和臣子就像看待自己一样，怎么会做出不慈爱的事？所以不孝不慈的现象就没有了。还有盗贼吗？看待别人的家就像自己的家，谁去偷窃？看待别人就像看待自己，谁去伤害？所以盗贼就没有了。还有大夫互相侵扰家族、诸侯互相攻伐国家的吗？看待别人的家族就像自己的家族，谁去侵扰？看待别人的国家就像自己的国家，谁去攻伐？所以大夫互相侵扰家族、诸侯互相攻伐国家的现象就没有了。如果使天下人都互相爱，国与国不相攻伐，家与家不相侵扰，盗贼没有，君臣父子都能孝慈，像这样天下就治理好了。',
