    translation: '锦瑟不知为何竟有五十根弦，每一弦每一柱都令人追忆青春年华。庄周在拂晓的梦中沉迷于蝴蝶的幻象，望帝将自己的春心托付给了杜鹃。沧海明月之下珍珠如同带着泪滴，蓝田暖日之中美玉升腾起缥缈的烟雾。这种情怀难道要等到成为追忆时才感伤？只是在当时就已经令人惘然若失了。',
