    translation: '屈原痛心怀王不能明辨是非，被谗言和谄媚所蒙蔽，邪曲的人损害了公正的人，端方正直的人不被容纳，所以忧愁深思写了《离骚》。"离骚"，就是遭遇忧愁的意思。天是人的开始，父母是人的根本。人处境困难就会追念根本，所以劳苦疲倦的时候，没有不呼喊上天的；病痛悲伤的时候，没有不呼唤父母的。屈原走正道行直路，竭尽忠诚和智慧来侍奉他的君主，谗佞的小人离间他，可以说是处境困难了。诚信却被怀疑，忠心却被诽谤，能没有怨恨吗？屈原写《离骚》，大概是从怨恨产生的。上面称述帝喾，下面说到齐桓公，中间叙述商汤、周武王，以此来讽刺当时的事。阐明道德的广大崇高，国家治乱的条理系统，没有不完全表现出来的。他的文章简约，他的言辞含蓄，他的志趣高洁，他的行为廉正。他记述的事情小但主旨极大，举的例子近但意义深远。他的志趣高洁，所以他记述的事物都是芬芳的；他的行为廉正，所以到死也不被容纳。自己远离污泥浊水之中，像蝉脱壳一样从污秽中解脱出来，浮游在尘埃之外，不沾染世俗的污垢，是洁白干净、出于污泥而不被污染的人。推究这种志趣，即使和日月争辉也是可以的。屈原被罢免之后，后来秦国想要攻打齐国，齐国和楚国合纵亲近，秦惠王对此感到忧虑。于是让张仪假装离开秦国，带着丰厚的礼物归顺楚国，说："秦国非常憎恨齐国，齐国和楚国合纵亲近，楚国如果能和齐国断交，秦国愿意献上商于一带六百里土地。"楚怀王贪心而相信了张仪，于是和齐国断交。齐国本来和楚国合纵亲近，楚国于是派使者到秦国去接受土地。张仪欺骗他说："我只和楚王约定了六里，没有听说过六百里。"楚国使者愤怒离去，回去报告怀王。怀王大怒，大举出兵攻打秦国。秦国发兵攻击楚军，在丹水、淅水一带大败楚军，斩首八万人，俘虏了楚将屈匄，于是夺取了楚国的汉中地区。怀王于是征发国中全部军队，深入秦国境内攻击，在蓝田交战。魏国听说后，偷袭楚国，到达邓地。楚军恐惧，从秦国撤回。而齐国竟然愤怒不救楚国，楚国陷入极大困境。第二年，秦国割让汉中之地给楚国议和。楚王说："我不想要土地，只想得到张仪来解恨。"张仪听说后，就说："用我一个张仪来换取汉中之地，请让我前往楚国。"到了楚国，又用厚礼贿赂当权的大臣靳尚，在怀王的宠妃郑袖面前设下诡辩。怀王竟然听信了郑袖，又放走了张仪。这时屈原已经被疏远，不再担任官职，出使齐国，回来后，劝谏怀王说："为什么不杀张仪？"怀王后悔了，追赶张仪，没有追上。此后，各诸侯国联合攻打楚国，大败楚军，杀了楚将唐眜。当时秦昭王和楚国通婚，想要和怀王会面。怀王想去，屈原说："秦国是虎狼之国，不可信任，不如不去。"怀王的小儿子子兰劝怀王去："为什么要断绝秦国的友好呢？"怀王最终还是去了。进入武关后，秦国埋伏军队断绝了他的后路，于是扣留怀王来索取割让土地。怀王愤怒，不听从。逃往赵国，赵国不接纳。又回到秦国，最终死在秦国，遗体运回安葬。长子顷襄王继位，任用他的弟弟子兰为令尹。楚人已经怨恨子兰劝怀王入秦而不能回来。屈原也嫉恨子兰，虽然被放逐，仍眷念楚国，关心怀王，不忘想要回去。希望君主能有一次醒悟，风俗能有一次改变。他保全君主振兴国家，想要使其恢复，一篇文章中三次表达了这个心愿。然而终究无可奈何，所以不能回去。最终因此而死。屈原来到江边，披散着头发在沼泽边行走吟唱，面色憔悴，形体枯瘦。渔父看见他，问道："你不是三闾大夫吗？为什么到了这步田地？"屈原说："世人都浑浊只有我清白，众人都醉了只有我清醒，所以被放逐。"渔父说："圣人不会被外物所拘泥，而能随世俗变化。世人都浑浊，为什么不顺随潮流推波助澜？众人都醉了，为什么不去吃他们的酒糟喝他们的薄酒？为什么怀抱美玉一般的高洁品格，而让自己被放逐呢？"屈原说："我听说，刚洗完头的人一定要弹去帽子上的灰尘，刚洗完澡的人一定要抖净衣服上的尘土。人又怎么能让自己洁净的身体，去承受污浊的事物呢？宁愿跳入湘江，葬身鱼腹之中。又怎么能以洁白纯真的品格，去蒙受世俗的尘垢呢？"于是写了《怀沙》这篇赋。之后抱着石头，就跳入汨罗江自杀了。太史公说：我读了《离骚》《天问》《招魂》《哀郢》，悲叹他的志向。到了长沙，经过屈原投江自尽的地方，未尝不掉下眼泪，想象他的为人。等到看见贾谊哀悼他的文章，又奇怪屈原凭他那样的才能游说诸侯，哪个国家不能容纳他，却让自己走到这一步！读了贾谊的《鵩鸟赋》，把死生同等看待，把去就看得很轻，我又茫然若失了。',
    literaryInfo: {
      authorBio: '司马迁（约前145年—约前87年），字子长，西汉伟大的史学家、文学家，著有《史记》，被鲁迅称为"史家之绝唱，无韵之《离骚》"。',
      background: '此文选自《史记·屈原贾生列传》，是中国文学史上最早的屈原传记，司马迁借写屈原抒发自己的悲愤。',
      significance: '此文是《史记》中最动情的篇章之一，司马迁借写屈原抒发自己的悲愤。首段"其文约，其辞微，其志洁，其行廉"以四句排比概括屈原的人格与文风，"信而见疑，忠而被谤"既是屈原的写照，也是司马迁的自况。后文详述怀王三次受骗、客死秦国的经过，屈原"虽放流，眷顾楚国，系心怀王"与"一篇之中三致志焉"的忠诚，最终"卒以此死"的悲剧，令人唏嘘。"推此志也，虽与日月争光可也"是文学史上对屈原最高的评价，也寄托了司马迁的人格理想。',
    },
