    translation: '唉！盛衰的道理，虽然说是天命，难道不是人为的吗？推究庄宗得到天下的原因，和他失去天下的原因，就可以知道了。世人说晋王临终的时候，把三支箭赐给庄宗并且告诉他说："梁国是我的仇敌；燕王是我扶持起来的；契丹和我约为兄弟，可是他们都背叛了晋国归顺了梁国。这三件事，是我的遗恨。给你三支箭，你一定不要忘记你父亲的志愿！"庄宗接受了箭并收藏在祖庙里。此后出兵打仗，就派属官用少牢之礼祭告祖庙，请下那三支箭，装在锦囊里，背着它走在队伍前面，等到凯旋时再把箭送回祖庙。当他用绳索捆绑燕王父子，用木匣装着梁国君臣的首级，进入太庙，把箭还给先王，向先王报告成功的消息时，他意气的旺盛，可以说是壮极了！等到仇敌已经消灭，天下已经平定，一个人夜里呼喊，叛乱的人四方响应，他仓皇向东出逃，还没见到叛贼士兵就离散了，君臣互相看着，不知道该归向哪里，以至于对天发誓剪断头发，眼泪流下来沾湿了衣襟，多么衰败啊！难道是得天下难而失天下容易吗？还是推究他成功失败的迹象，都是由于人为的原因呢？《尚书》说："自满招来损害，谦虚得到益处。"忧虑劳苦可以使国家兴盛，安逸享乐可以使自身败亡，这是自然的道理。所以当他兴盛的时候，全天下的豪杰，没有谁能和他争雄；等到他衰败的时候，几十个伶人围困他，就身死国灭，被天下人耻笑。祸患常常是从微小的事情积累起来的，而智勇的人常常被自己溺爱的事物所困扰，难道只是伶人吗？',
