    translation: '孔雀向东南飞去，每飞五里就徘徊一阵。十三岁能织白绢，十四岁学会了裁衣，十五岁会弹箜篌，十六岁能诵读诗书。十七岁做了你的妻子，心中常常痛苦悲伤。你既然做了府吏，遵守职守感情不移。我留在空房中，相见的日子常常很稀少。鸡叫就上机织布，夜夜都不能歇息。三天织成五匹布，婆婆还嫌织得慢。不是我织得慢，是你家的媳妇太难做了！我受不了驱使，白白留着也没有用。你可以禀告婆婆，趁早把我送回娘家。府吏听了这些话，到堂上禀告母亲：儿子本来就没有做官的福相，幸好娶到了这个妻子。结发成为夫妻，死后也要做朋友。共同生活才两三年，结婚的时间还不算长。她的行为没有偏差，怎么会招致不满呢？母亲对府吏说：你怎么这样愚蠢！这个媳妇没有礼节，行动自己做主。我心中早就怀着不满，你怎么能自己做主！东邻有个贤惠的女子，自己叫秦罗敷。姿态可爱无人能比，母亲替你去求亲。赶快把她休了，休了千万不要留！府吏长跪禀告，恭敬地对母亲说：今天如果休了这个妻子，一辈子再也不娶了！母亲听了，捶着床大发脾气：你这小子什么都不怕，怎么敢帮媳妇说话！我已经对她失去了恩义，绝不会答应你的请求！',
