    translation: '淮南东路的著名都市，竹西亭所在的美景之处，我解下马鞍稍作停留。走过当年春风十里的扬州路，如今全是青青的荠菜和麦子。自从金兵南侵长江退去以后，废弃的池塘和高大的树木，至今仍然厌恶谈论战争。渐渐地到了黄昏，凄清的号角声吹来寒意，都笼罩在这座空城里。杜牧有卓越的鉴赏力，算起来今天重新来到这里一定震惊。即使有写"豆蔻"词的工巧，有"青楼梦"的绮丽，也难以写出此刻深沉的感情。二十四桥还在，桥下水波荡漾，冷月悄然无声。想到桥边的红色芍药花，年年还不知道为谁而开？',
