    translation: '我这个痴人办完了公家的事，在快阁上靠着栏杆欣赏傍晚晴空。千山落叶尽褪，天空辽阔远大；一道澄澈的江水，月色分外明朗。琴弦已经因为知音难遇而断绝，青眼只因为美酒才睁开。乘坐万里归船吹起长笛，我这颗心早已和白鸥结盟归隐。',
