    translation: '项脊轩，就是原来的南阁子。室内只有一丈见方，可以容纳一个人居住。这是一座百年老屋，灰尘和泥土渗漏，雨水往下倾注；每次移动桌案，环视四周没有可以安放的地方。又朝北，照不到太阳，过了中午就昏暗了。我稍加修葺，使屋顶不再漏雨。前面开了四扇窗户，院墙围着庭院，用来挡住南面射来的阳光，日光反射，室内才明亮起来。又在庭院里混杂种植了兰花、桂树、竹子和其他树木，旧时的栏杆也就增添了美景。借来的书摆满了书架，我时而安居时而仰首长啸吟唱，有时静静地端坐，可以听到各种自然的声音；庭院台阶上静悄悄的，小鸟不时飞来啄食，人来了也不飞走。十五的夜晚，明月照亮半截墙壁，桂树的影子交错斑驳，风吹过影子摇动，轻盈可爱。然而我住在这里，有很多可喜的事，也有很多可悲的事。在这之前，庭院南北相通是一个整体。等到伯父叔父们分了家，里里外外设置了很多小门，墙壁到处都是。东家的狗对着西家叫，客人要越过厨房去赴宴，鸡都栖息在大厅里。庭院中起初是篱笆，后来是墙壁，一共变了两次。家里有一个老妇人，曾经住在这里。老妇人，是去世的祖母的婢女，哺育过两代人，母亲待她很好。房间的西边和内室相连，母亲曾经来过一次。老妇人常常对我说："那个地方，你母亲站在那里。"老妇人又说："你姐姐在我怀里，呱呱地哭泣；你母亲用手指敲着门板说：\'孩子冷了吗？要吃东西吗？\'我从门板外边应答她。"话还没说完，我就哭了，老妇人也哭了。我从十五岁起就在轩中读书，有一天，祖母来看我说："我的孩子，好久没见到你的身影了，怎么整天默默地待在这里，太像个女孩子了？"临走时，用手关上门，自言自语说："我家读书很久没有功名了，这孩子的成就，是可以期待的吧！"过了一会儿，拿了一块象牙笏板来，说："这是我祖父太常公在宣德年间拿着上朝用的，将来你会用到它！"看到这些遗物，就像在昨天一样，让人忍不住放声大哭。',
