      authorBio: '归有光（1506年—1571年），字熙甫，号震川，明代散文家，与王慎中、唐顺之并称"嘉靖三大家"。',
      background: '此文分两次写成，前半部分作于青年时期，补记部分作于十余年后。项脊轩是归有光的书房，因追忆祖母、母亲而作。',
      significance: '此文被誉为明代散文第一，以项脊轩为线索串联起家族的盛衰与亲人的温情。"借书满架，偃仰啸歌"写读书之乐，"桂影斑驳，风移影动，珊珊可爱"写月下之美，但"多可喜，亦多可悲"一转，将读者带入深沉的感伤。"某所，而母立于兹"的细节追忆、祖母"吾家读书久不效，儿之成，则可待乎"的殷切期望、老妪"语未毕，余泣"的场景，无不以小见大，于细微处见深情。',
