    translation: '永和九年，是癸丑年，暮春三月初，在会稽郡山阴县的兰亭聚会，举行修禊活动。众多贤士都到了，年长年少的都聚集在一起。这里有高峻的山岭，茂密的树林和修长的竹子，又有清澈湍急的水流，映衬环绕在左右，引它作为流觞的曲水，依次坐在水边。虽然没有管弦齐鸣的盛况，但喝酒吟诗，也足够畅快地抒发幽深的感情了。这一天，天气晴朗空气清新，和风温暖舒畅。抬头观看宇宙的广大，低头审视万物的繁多，借此纵目观赏开阔胸怀，足以穷尽视听的快乐，实在快乐啊。人们互相交往，很快就度过一生。有的人在室内倾吐自己的胸怀，面对面地交谈；有的人寄情于所爱好的事物，放纵不羁不受礼法拘束。虽然取舍千差万别，沉静和急躁各不相同，当他们对所接触的事物感到高兴时，一时自得其乐，快乐自足，不知道衰老即将到来；等到对已得到的东西感到厌倦，感情随着事情的变化而变化，感慨就随之而来了。以前所喜爱的，顷刻之间已经成为旧迹，尚且不能不因为它引起感触，何况寿命长短听从造化，最终都要归于消亡！古人说："死生也是件大事啊。"怎能不悲痛呢！每次看到古人产生感慨的原因，就像符契那样相合，未曾不面对文章叹息哀悼，不能在心里明白理解。本来就知道把死和生同等看待是荒诞的，把长寿和短命等同起来是虚妄的。后代人看今天，也就像今天的人看从前一样，可悲啊！所以一一记下当时与会的人，收录他们所作的诗篇，虽然时代不同事情不同，但引起感触的原因，那情致是一样的。后代的读者，也将对这些诗文有所感慨。',
    literaryInfo: {
      authorBio: '王羲之（303年—361年），字逸少，东晋书法家，被后世尊为"书圣"，其《兰亭集序》被誉为"天下第一行书"。',
      background: '永和九年（353年）三月三日，王羲之与谢安等四十一人在兰亭集会修禊，饮酒赋诗，王羲之作此序。',
      significance: '此文是中国书法史和文学史上的千古名篇，由兰亭雅集之乐转入对死生的深沉思考。"天朗气清，惠风和畅"是千古传诵的名句，"固知一死生为虚诞，齐彭殇为妄作"则直接否定庄子的齐死生观，肯定了生命的珍贵。"后之视今，亦犹今之视昔"以时间的永恒轮回写出人类共通的悲慨，既是哲思也是深情。全篇由乐转悲再转达观，情感层层深入，书法更是被尊为"天下第一行书"，文与书相得益彰。',
    },
