      background: '此文是柳宗元早年的作品，借种树之理来谈治民之道，是寓言体传记散文。',
      significance: '此文是柳宗元寓言体传记散文的代表作，以种树之喻论治民之道。"能顺木之天以致其性焉尔"是全篇的核心思想，与老子"无为而治"一脉相承。"其莳也若子，其置也若弃"的辩证法则揭示了养护的真谛——既要悉心栽种又要放手让其自然生长。"虽曰爱之，其实害之；虽曰忧之，其实仇之"的论断尤为深刻，对过度管理、过度干预有深刻的警示意义，以小见大，借树喻政，是唐代寓言文的杰作。',
